import { cache } from "react";
import type { User } from "@supabase/supabase-js";
import { createClient } from "@/lib/supabase-server";
import { settingsSchema } from "@/lib/settings";

// A session confirmed with Supabase Auth is trusted for a minute, so most navigations skip that
// round trip. Signing out here clears the cookie at once; a session revoked elsewhere stops
// working within the minute. Failed checks are never remembered.
const CONFIRMED_MS = 60_000;
const confirmed = new Map<string, { user: User; until: number }>();

async function confirmUser(supabase: Awaited<ReturnType<typeof createClient>>, userId: string, sessionId: string | undefined) {
  const key = sessionId ? `${userId}:${sessionId}` : null;
  const known = key ? confirmed.get(key) : undefined;
  if (known && known.until > Date.now()) return known.user;
  const { data: { user }, error } = await supabase.auth.getUser();
  if (error || !user || user.id !== userId) {
    if (key) confirmed.delete(key);
    throw new Error("Unauthorized");
  }
  if (key) {
    if (confirmed.size >= 1000) confirmed.delete(confirmed.keys().next().value!);
    confirmed.set(key, { user, until: Date.now() + CONFIRMED_MS });
  }
  return user;
}

// Memoized per request so the root layout and the page share one auth and workspace lookup.
export const requireWorkspace = cache(async () => {
  const supabase = await createClient();
  // getClaims verifies the JWT locally, so the RLS-scoped workspace read can run while
  // the session is confirmed with Supabase Auth (or was within the last minute).
  const { data: claims } = await supabase.auth.getClaims();
  const userId = claims?.claims.sub;
  if (!userId) throw new Error("Unauthorized");
  const [user, { data, error }] = await Promise.all([
    confirmUser(supabase, userId, claims.claims.session_id),
    supabase.from("workspaces").select("id, owner_id, display_currency, workspace_settings(*)").eq("owner_id", userId).maybeSingle(),
  ]);
  if (error || !data) throw new Error("Workspace unavailable");
  const { workspace_settings: stored, ...workspace } = data as typeof data & { workspace_settings: unknown };
  const settings = settingsSchema.parse(stored ?? {});
  return { supabase, user, settings, workspace: { ...workspace, timezone: settings.timezone, locale: settings.locale, settings } };
});

"use client";

import Link from "next/link";
import { useRef, useState, type ComponentProps } from "react";

/**
 * A nav link that prefetches its whole page once the pointer rests on it (or it gets focus or a
 * touch), so the server is already rendering when the click lands. The short delay skips links the
 * pointer only sweeps past; the current page is never prefetched. Prefetched pages are reused for
 * at most staleTimes.static (30 s, next.config.ts).
 */
export function IntentLink({ onPointerEnter, onPointerLeave, onFocus, onBlur, onTouchStart, ...props }: ComponentProps<typeof Link>) {
  const [intent, setIntent] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const current = props["aria-current"] === "page";
  const show = () => { if (!current) setIntent(true); };
  const hide = () => { clearTimeout(timer.current); setIntent(false); };
  return <Link {...props} prefetch={intent ? true : null}
    onPointerEnter={event => { onPointerEnter?.(event); clearTimeout(timer.current); timer.current = setTimeout(show, 60); }}
    onPointerLeave={event => { onPointerLeave?.(event); hide(); }}
    onFocus={event => { onFocus?.(event); show(); }}
    onBlur={event => { onBlur?.(event); hide(); }}
    onTouchStart={event => { onTouchStart?.(event); show(); }} />;
}
"use client";

import { useEffect, useRef, useState, useSyncExternalStore, type CSSProperties } from "react";

type Theme = "light" | "dark" | "system";

function subscribeTheme(notify: () => void) {
  const observer = new MutationObserver(notify);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  return () => observer.disconnect();
}
// A "system" frame gets no theme and follows the OS itself, like the app does.
function readTheme(): Theme {
  const theme = document.documentElement.dataset.theme;
  return theme === "light" || theme === "dark" ? theme : "system";
}

const FIT_MIN = 160, FIT_MAX = 560, FIT_START = 320;

/**
 * A sandboxed artifact from its frame route, in the app's current theme. Server pages pass the theme they
 * rendered, so the frame is in the HTML and starts loading before hydration. `fit` sizes it to the page's reported content height.
 */
export function ArtifactFrame({ src, title, theme: rendered = "system", fit = false, loading, className, style }: { src: string; title: string; theme?: Theme; fit?: boolean; loading?: "lazy"; className?: string; style?: CSSProperties }) {
  const theme = useSyncExternalStore(subscribeTheme, readTheme, () => rendered);
  const frame = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(FIT_START);
  useEffect(() => {
    if (!fit) return;
    const onMessage = (event: MessageEvent) => {
      if (event.source !== frame.current?.contentWindow) return;
      const reported = Number(event.data?.moneoHeight);
      if (Number.isFinite(reported)) setHeight(Math.min(FIT_MAX, Math.max(FIT_MIN, Math.ceil(reported))));
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, [fit]);
  const sized = fit ? { height, ...style } : style;
  return <iframe ref={frame} title={title} sandbox="allow-scripts" loading={loading} src={theme === "system" ? src : `${src}${src.includes("?") ? "&" : "?"}theme=${theme}`}
    className={`border-0 ${className ?? ""}`} style={{ colorScheme: theme === "system" ? "light dark" : theme, ...sized }} />;
}

const THUMB_WIDTH = 800, THUMB_HEIGHT = 500;

/** A scaled-down, non-interactive live preview; it only loads once scrolled near the viewport. */
export function ArtifactThumbnail({ src, title }: { src: string; title: string }) {
  const box = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(0);
  useEffect(() => {
    const element = box.current!;
    const observer = new ResizeObserver(() => setScale(element.clientWidth / THUMB_WIDTH));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return <div ref={box} inert className="pointer-events-none relative aspect-[8/5] overflow-hidden bg-background">
    {scale > 0 && <ArtifactFrame src={src} title={`Preview of ${title}`} loading="lazy" className="absolute left-0 top-0 origin-top-left"
      style={{ width: THUMB_WIDTH, height: THUMB_HEIGHT, transform: `scale(${scale})` }} />}
  </div>;
}
