import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { ARTIFACT_FRAME_CSP, artifactDocument, artifactQueriesSchema, runArtifactQueries } from "@/lib/ai/artifact-data";
import { calendarDate } from "@/lib/finance/calendar";

const querySchema = z.object({
  v: z.coerce.number().int().min(1).optional(),
  view: z.enum(["page", "widget"]).default("page"),
  theme: z.enum(["light", "dark"]).optional(),
});

/**
 * The artifact document on its own URL, so pages that show artifacts (gallery previews, Home cards,
 * the viewer) render at once and each frame reruns its saved queries in parallel.
 */
export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return new Response("Unauthorized", { status: 401 }); }
  const id = z.uuid().safeParse((await params).id);
  const query = querySchema.safeParse(Object.fromEntries(new URL(request.url).searchParams));
  if (!id.success || !query.success) return new Response("Not found", { status: 404 });
  const { supabase, workspace } = context;
  const { v, view, theme } = query.data;
  const versions = supabase.from("artifact_versions").select("html, queries, created_at").eq("workspace_id", workspace.id).eq("artifact_id", id.data);
  const [artifact, version] = await Promise.all([
    supabase.from("artifacts").select("id").eq("workspace_id", workspace.id).eq("id", id.data).is("deleted_at", null).maybeSingle(),
    (v ? versions.eq("version", v) : versions.order("version", { ascending: false }).limit(1)).maybeSingle(),
  ]);
  if (artifact.error || version.error) throw artifact.error ?? version.error;
  if (!artifact.data || !version.data) return new Response("Not found", { status: 404 });
  const queries = artifactQueriesSchema.safeParse(version.data.queries);
  const data = await runArtifactQueries(queries.success ? queries.data : [], context, calendarDate(version.data.created_at, context.settings.timezone));
  return new Response(artifactDocument(version.data.html, data, { view, theme }), {
    headers: { "Content-Type": "text/html; charset=utf-8", "Content-Security-Policy": ARTIFACT_FRAME_CSP, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff" },
  });
}

import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { requireAiScope, type AiDataScope } from "@/lib/settings";
import { cashflow, financeToolSchemas, getBalances, listAccounts, listGoals, searchTransactions } from "@/lib/finance/tools";
import { investigationSchema } from "@/lib/finance/investigation";
import { runInvestigation } from "@/lib/finance/investigation-reader";
import { listRecurring } from "@/lib/ai/recurring-proposals";
import { calendarDate } from "@/lib/finance/calendar";
import { readableToolOutput } from "@/lib/ai/tool-output";

type Context = Awaited<ReturnType<typeof requireWorkspace>>;
const empty = z.object({}).strict();
const imports = (context: Context) => context.settings.ai_data_scopes.includes("imports");

// The only data an artifact can see: read-only finance queries the app runs itself. The same
// sources are the builder's tools and the viewer's refresh, so a saved query always reruns.
export const ARTIFACT_SOURCES = {
  investigate: { description: "Spending/income totals, groupings and rankings over exact dates, accounts, categories and merchants.", input: investigationSchema, scopes: ["accounts", "transactions"],
    run: (input: unknown, context: Context) => runInvestigation(input, context, { canReadImports: imports(context) }) },
  cashflow: { description: "Posted income and spending for a period in one currency.", input: financeToolSchemas.periodInput, scopes: ["transactions"],
    run: (input: unknown, context: Context) => cashflow(input, context, imports(context)) },
  transactions: { description: "Transactions, newest first, filtered by text, dates and amounts (max 50).", input: financeToolSchemas.searchInput, scopes: ["transactions"],
    run: (input: unknown, context: Context) => searchTransactions(input, context) },
  balances: { description: "Current dated account balances.", input: empty, scopes: ["accounts"], run: (_: unknown, context: Context) => getBalances(context, imports(context)) },
  accounts: { description: "The user's accounts.", input: empty, scopes: ["accounts"], run: (_: unknown, context: Context) => listAccounts(context) },
  recurring: { description: "Confirmed recurring payments and income (name, amount, direction, cadence, next date, category) plus detected patterns still awaiting confirmation.", input: empty, scopes: ["planning", "transactions"],
    run: (_: unknown, context: Context) => listRecurring(context) },
  goals: { description: "The user's savings goals.", input: empty, scopes: ["planning"], run: (_: unknown, context: Context) => listGoals(context) },
} satisfies Record<string, { description: string; input: z.ZodType; scopes: AiDataScope[]; run: (input: unknown, context: Context) => Promise<unknown> }>;
export type ArtifactSource = keyof typeof ARTIFACT_SOURCES;
const SOURCE_KEYS = Object.keys(ARTIFACT_SOURCES) as [ArtifactSource, ...ArtifactSource[]];

export const artifactQuerySchema = z.object({
  name: z.string().regex(/^[a-zA-Z_][a-zA-Z0-9_]{0,39}$/),
  source: z.enum(SOURCE_KEYS),
  input: z.record(z.string(), z.unknown()).default({}),
}).strict().superRefine((query, issue) => {
  const parsed = ARTIFACT_SOURCES[query.source].input.safeParse(query.input);
  if (!parsed.success) issue.addIssue({ code: "custom", message: `${query.name}: ${parsed.error.issues[0]?.message ?? "invalid input"}` });
});
export const artifactQueriesSchema = z.array(artifactQuerySchema).max(12)
  .refine(queries => new Set(queries.map(query => query.name)).size === queries.length, "Query names must be unique");
export type ArtifactQuery = z.infer<typeof artifactQuerySchema>;

/** One source's result as the artifact (and builder) reads it: formatted money, no internal evidence. */
export async function runArtifactSource(source: ArtifactSource, input: unknown, context: Context) {
  const definition = ARTIFACT_SOURCES[source];
  requireAiScope(context.settings, ...definition.scopes);
  return readableToolOutput(await definition.run(definition.input.parse(input), context));
}

const DATE_VALUE = /^\d{4}-\d{2}-\d{2}$/;
const DAY_MS = 86_400_000;

/** A query input with each saved from/to date moved forward by days. Page cursors are dropped: they pin the old window. */
export function rollQueryDates(input: unknown, days: number): unknown {
  if (!days) return structuredClone(input);
  if (Array.isArray(input)) return input.map(item => rollQueryDates(item, days));
  if (!input || typeof input !== "object") return input;
  return Object.fromEntries(Object.entries(input).map(([key, value]) => {
    if ((key === "from" || key === "to") && typeof value === "string" && DATE_VALUE.test(value)) return [key, new Date(Date.parse(value) + days * DAY_MS).toISOString().slice(0, 10)];
    if (key === "page" && value && typeof value === "object" && !Array.isArray(value)) {
      const page = { ...value } as Record<string, unknown>;
      delete page.cursor;
      return [key, rollQueryDates(page, days)];
    }
    return [key, rollQueryDates(value, days)];
  }));
}

/** Runs saved queries fresh; one failing query reports its error instead of hiding the rest. savedOn is the ISO date the version was saved. */
export async function runArtifactQueries(queries: ArtifactQuery[], context: Context, savedOn?: string): Promise<Record<string, unknown>> {
  // Saved periods keep their length and move with time, so an artifact always shows the latest window.
  const days = savedOn ? Math.round((Date.parse(calendarDate(new Date(), context.settings.timezone)) - Date.parse(savedOn)) / DAY_MS) : 0;
  return Object.fromEntries(await Promise.all(queries.map(async query => {
    try { return [query.name, await runArtifactSource(query.source, days > 0 ? rollQueryDates(query.input, days) : query.input, context)]; }
    catch (cause) { return [query.name, { error: cause instanceof Error ? cause.message : "Data unavailable" }]; }
  })));
}

const CSP = "default-src 'none'; script-src 'unsafe-inline' https://cdn.jsdelivr.net; style-src 'unsafe-inline'; img-src data: blob:; font-src data:";
/** Sent as a header too: sandbox keeps the page in an opaque origin even if the frame URL is opened directly. */
export const ARTIFACT_FRAME_CSP = `${CSP}; sandbox allow-scripts; frame-ancestors 'self'`;

export type ArtifactView = "page" | "widget";
export type ArtifactTheme = "light" | "dark";

// The app's palette, so a page can match Moneo; light-dark() follows the color-scheme set below.
const TOKENS = ":root{--moneo-bg:light-dark(#f4f3ee,#0f1011);--moneo-card:light-dark(#fff,#16171a);--moneo-fg:light-dark(#141413,#eeece6);--moneo-muted:light-dark(#5c5d58,#a3a39e);"
  + "--moneo-border:light-dark(#e2e0d8,#24262a);--moneo-accent:light-dark(#4a6400,#cbf26b);--moneo-positive:light-dark(#3f6b00,#cbf26b);--moneo-negative:light-dark(#b42318,#ff7a6b);"
  + "--moneo-font:ui-sans-serif,system-ui,sans-serif;--moneo-mono:ui-monospace,Consolas,monospace}";
// Reports the content height so an embedding card can size the frame to fit.
const FIT = "addEventListener('load',function(){if(parent===window)return;var post=function(){parent.postMessage({moneoHeight:document.body.scrollHeight},'*')};new ResizeObserver(post).observe(document.body);post()})";

/** The sandboxed document: a strict CSP, the fresh data and the app theme come before any generated markup. */
export function artifactDocument(html: string, data: Record<string, unknown>, { view = "page", theme }: { view?: ArtifactView; theme?: ArtifactTheme } = {}) {
  // Escaping "<" keeps data like "</script>" inside the JSON literal.
  const json = JSON.stringify(data).replace(/</g, "\\u003c");
  const head = `<meta http-equiv="Content-Security-Policy" content="${CSP}"><script>window.MONEO_DATA=${json};window.MONEO_VIEW="${view}";${FIT}</script>`
    + `<style>${TOKENS}:root{color-scheme:${theme ?? "light dark"}}</style>`;
  return /<head[^>]*>/i.test(html) ? html.replace(/<head[^>]*>/i, match => match + head) : head + html;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AlertCircle, ArrowUp, Ban, CheckCircle2, Loader2, Mic, MicOff, PhoneOff, X } from "lucide-react";
import { IouCard } from "@/components/iou-card";
import { useVoiceCall } from "@/lib/ai/use-voice-call";
import type { ChatAnswer } from "@/lib/ai/use-chat-request";

type OrbState = "connecting" | "listening" | "muted" | "thinking" | "speaking" | "idle";
const ORB_TONES: Record<OrbState, string> = {
  connecting: "[--orb-a:var(--color-ai-border)] [--orb-b:var(--color-ai-soft)]",
  listening: "[--orb-a:var(--color-ai)] [--orb-b:var(--color-ai-border)]",
  muted: "[--orb-a:var(--color-subtle)] [--orb-b:var(--color-muted)]",
  thinking: "[--orb-a:var(--color-ai)] [--orb-b:var(--color-lime)]",
  speaking: "[--orb-a:var(--color-lime)] [--orb-b:var(--color-brand)]",
  idle: "[--orb-a:var(--color-input)] [--orb-b:var(--color-muted)]",
};

/** The orb follows whoever is talking: its glow and ring swell with the voice, it turns while Moneo works, and it holds still for reduced motion. */
function Orb({ levels, state }: { levels: () => { mic: number; moneo: number }; state: OrbState }) {
  const orb = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let frame = 0, smooth = 0;
    const tick = () => {
      const { mic, moneo } = levels();
      smooth += (Math.max(mic, moneo) - smooth) * 0.2;
      orb.current?.style.setProperty("--level", smooth.toFixed(3));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [levels]);
  const still = state === "idle" || state === "muted";
  return <div ref={orb} aria-hidden="true" className={`relative grid size-36 shrink-0 place-items-center sm:size-52 ${ORB_TONES[state]}`}>
    <div className="absolute inset-2 rounded-full bg-[radial-gradient(circle,var(--orb-a),transparent_68%)] opacity-45 blur-2xl" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.5))" }} />
    <div className="absolute inset-4 rounded-full border sm:inset-5 border-[color-mix(in_oklab,var(--orb-a)_40%,transparent)]" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.3))" }} />
    <div className={still ? "" : "motion-safe:animate-orb-breathe"}>
      <div className="relative size-24 overflow-hidden rounded-full shadow-[inset_0_-10px_30px_rgb(0_0_0/0.18),0_14px_40px_-14px_var(--orb-a)] sm:size-32" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.14))" }}>
        <div className={`absolute -inset-1/4 blur-md bg-[conic-gradient(from_90deg,var(--orb-a),var(--orb-b),var(--orb-a))] ${state === "thinking" || state === "connecting" ? "motion-safe:animate-orb-spin" : ""}`} />
        <div className="absolute inset-0 rounded-full bg-[radial-gradient(circle_at_32%_28%,rgb(255_255_255/0.5),transparent_48%)]" />
      </div>
    </div>
  </div>;
}

/** A live voice call with Moneo: speak or type, see the requests it is working on, and tap the cards it makes. The full transcript is saved with the call. */
export function VoiceCall({ conversationId, onAnswer, onEnded, onClose }: { conversationId: string; onAnswer: (question: string, answer: ChatAnswer) => void; onEnded: () => void; onClose: () => void }) {
  return <VoiceCallView call={useVoiceCall(conversationId, onAnswer, onEnded)} onClose={onClose} />;
}

/** The call screen for a call's state, kept apart from the connection so each state can be rendered alone. */
export function VoiceCallView({ call, onClose }: { call: ReturnType<typeof useVoiceCall>; onClose: () => void }) {
  const [text, setText] = useState("");
  const body = useRef<HTMLDivElement>(null);
  useEffect(() => { body.current?.scrollTo({ top: body.current.scrollHeight }); }, [call.tasks]);
  const last = call.captions.at(-1);
  const live = call.status === "live";
  const open = live || call.status === "connecting";
  const state: OrbState = call.status === "connecting" ? "connecting" : !live ? "idle" : last?.role === "assistant" && !call.thinking ? "speaking" : call.thinking ? "thinking" : call.muted ? "muted" : "listening";
  const label = { connecting: "Connecting…", listening: "Listening", muted: "You're muted", thinking: "Working on it", speaking: "Moneo is talking", idle: call.status === "ended" ? "Call ended" : "Call dropped" }[state];
  const running = call.tasks.filter(task => task.status === "running");
  const round = "grid size-16 place-items-center rounded-full transition-[background-color,transform] active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-40";

  return <section role="dialog" aria-modal="true" aria-label="Voice call with Moneo" className="fixed inset-0 z-50 flex flex-col bg-background lg:sticky lg:top-19 lg:z-auto lg:h-[calc(100dvh-4.75rem)]">
    <header className="flex items-center justify-between gap-3 border-b border-border px-4 pt-[max(0.75rem,env(safe-area-inset-top))] pb-3 sm:px-8 lg:pt-3">
      <p className="font-display text-lg font-semibold">Call with Moneo</p>
      {live && <span className="inline-flex items-center gap-1.5 rounded-full bg-success-soft px-2.5 py-1 text-xs font-medium text-success"><span className="size-1.5 rounded-full bg-current motion-safe:animate-pulse" aria-hidden="true" />Live</span>}
    </header>
    <div ref={body} className="scrollbar-none mx-auto flex min-h-0 w-full max-w-[720px] flex-1 flex-col overflow-y-auto px-4 sm:px-8">
      <div className="flex flex-col items-center pt-4 sm:pt-8">
        <Orb levels={call.levels} state={state} />
        <p role="status" className="flex h-7 items-center gap-2 font-display text-lg font-medium">{state === "connecting" && <Loader2 className="size-4 text-ai motion-safe:animate-spin" aria-hidden="true" />}{label}</p>
      </div>
      {call.error && <p role="alert" className="mt-4 flex items-start gap-2 rounded-xl border border-danger/30 bg-danger-soft px-3.5 py-2.5 text-sm text-danger"><AlertCircle className="mt-0.5 size-4 shrink-0" aria-hidden="true" />{call.error}</p>}
      {!call.tasks.length && live && <p className="mt-6 text-center text-[15px] text-muted-foreground sm:text-base">Say hi, ask about your money, or tell Moneo what you spent.</p>}
      {call.tasks.length > 0 && <div className="mt-5">
        <p className="eyebrow pb-2">{running.length ? `Working on ${running.length} of ${call.tasks.length}` : "All done"}</p>
        <ul className="space-y-1.5" aria-label="Tasks">
          {call.tasks.slice(-6).map(task => <li key={task.requestId} className="flex min-h-14 items-center gap-3 rounded-xl border border-border bg-card py-1.5 pr-1 pl-3.5 text-sm">
            <TaskIcon status={task.status} />
            <span className="min-w-0 flex-1"><span className="block truncate font-medium">{task.text}</span><span className={`block text-xs ${task.status === "failed" ? "text-danger" : "text-muted-foreground"}`}>{task.step}</span></span>
            {task.status === "running" && <button type="button" onClick={() => void call.cancel(task.requestId)} aria-label={`Stop “${task.text}”`} className="grid size-11 shrink-0 place-items-center rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ai"><X className="size-4" aria-hidden="true" /></button>}
          </li>)}
        </ul>
      </div>}
      {call.cards.length > 0 && <div aria-label="Cards to review" role="region" className="mt-5">
        <p className="eyebrow">Tap to save · nothing is saved until you do</p>
        {call.cards.map(id => <IouCard key={id} id={id} />)}
      </div>}
      <div className="h-4 shrink-0" />
    </div>
    <footer className="border-t border-border px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))] sm:px-8">
      {open && <form onSubmit={event => { event.preventDefault(); call.typed(text); setText(""); }} className="mx-auto mb-4 flex max-w-[720px] items-center gap-2">
        <label className="sr-only" htmlFor="call-text">Type to Moneo</label>
        <input id="call-text" value={text} onChange={event => setText(event.target.value)} maxLength={4000} placeholder="Or type a message…" autoComplete="off"
          className="h-11 min-w-0 flex-1 rounded-full border border-input bg-card px-4 text-[15px] transition-colors focus:border-muted-foreground/60 focus:outline-none" />
        <button aria-label="Send" disabled={!text.trim()} className="grid size-11 shrink-0 place-items-center rounded-full bg-primary text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-30"><ArrowUp className="size-5" aria-hidden="true" /></button>
      </form>}
      <div className="flex items-start justify-center gap-10">
        <div className="flex flex-col items-center gap-1.5">
          <button type="button" onClick={call.toggleMute} aria-pressed={call.muted} aria-label={call.muted ? "Unmute" : "Mute"} disabled={!live}
            className={`${round} ${call.muted ? "bg-foreground text-background" : "border border-border bg-card hover:bg-muted"}`}>{call.muted ? <MicOff className="size-6" aria-hidden="true" /> : <Mic className="size-6" aria-hidden="true" />}</button>
          <span aria-hidden="true" className="text-xs text-muted-foreground">{call.muted ? "Unmute" : "Mute"}</span>
        </div>
        <div className="flex flex-col items-center gap-1.5">
          <button type="button" onClick={onClose} aria-label={open ? "End call" : "Close"} className={`${round} bg-danger text-white hover:bg-danger/90`}>{open ? <PhoneOff className="size-6" aria-hidden="true" /> : <X className="size-6" aria-hidden="true" />}</button>
          <span aria-hidden="true" className="text-xs text-muted-foreground">{open ? "End" : "Close"}</span>
        </div>
      </div>
    </footer>
  </section>;
}

/** Where one task stands: a spinner while running, then a tick, a warning or a stop mark. */
function TaskIcon({ status }: { status: string }) {
  const icon = "size-4 shrink-0";
  if (status === "running") return <Loader2 className={`${icon} text-ai motion-safe:animate-spin`} aria-label="Running" />;
  if (status === "done") return <CheckCircle2 className={`${icon} text-success`} aria-label="Done" />;
  if (status === "failed") return <AlertCircle className={`${icon} text-danger`} aria-label="Failed" />;
  return <Ban className={`${icon} text-subtle`} aria-label="Stopped" />;
}
