"use client";

import { useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Sparkles } from "lucide-react";
import { VoiceInput } from "@/components/voice-input";
import { withSpoken } from "@/components/chat-composer";

/** Builds a new artifact, or a new version of one; the AI can take a minute or two. */
export function ArtifactPrompt({ artifactId, defaultValue = "", placeholder }: { artifactId?: string; defaultValue?: string; placeholder: string }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const router = useRouter();
  const input = useRef<HTMLTextAreaElement>(null);
  // Spoken words join what is typed; Send then submits the request as typed words would.
  function speak(text: string, submit: boolean) {
    const field = input.current;
    if (!field) return;
    field.value = withSpoken(field.value, text).slice(0, 4000);
    if (submit) field.form?.requestSubmit(); else field.focus();
  }
  async function submit(form: HTMLFormElement) {
    const message = String(new FormData(form).get("message") ?? "").trim();
    if (!message) return;
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/artifacts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ artifactId, message }) });
      const body = await response.json().catch(() => ({}));
      if (!response.ok || !body.id) throw new Error(body.error ?? "Could not build the artifact");
      form.reset();
      router.push(`/ai/artifacts/${body.id}`);
      router.refresh();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not build the artifact"); }
    finally { setBusy(false); }
  }
  return <form onSubmit={event => { event.preventDefault(); void submit(event.currentTarget); }} className="relative grid gap-2">
    <textarea ref={input} name="message" required maxLength={4000} rows={artifactId ? 3 : 4} defaultValue={defaultValue} placeholder={placeholder} disabled={busy} aria-label={placeholder}
      onKeyDown={event => { if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) event.currentTarget.form?.requestSubmit(); }}
      className="w-full resize-y rounded-lg border border-border bg-card px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring" />
    <div className="flex items-center justify-between gap-2">
      {error ? <span role="alert" className="text-xs text-danger">{error}</span> : <span className="text-xs text-muted-foreground">{busy ? "Building… this can take a minute." : "Uses your real data, read-only."}</span>}
      <span className="flex items-center gap-1.5"><VoiceInput disabled={busy} onSend={text => speak(text, true)} onDone={text => speak(text, false)} />
      <button type="submit" disabled={busy} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50">
        <Sparkles className="size-3.5" aria-hidden="true" />{busy ? "Building…" : artifactId ? "Update" : "Build"}</button></span>
    </div>
  </form>;
}

import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { Check, ChevronLeft, ChevronRight, HousePlus, Maximize2, Minimize2 } from "lucide-react";
import { requireWorkspace } from "@/lib/auth";
import { ArtifactFrame } from "@/components/artifact-frame";
import { loadArtifactBuilds } from "@/lib/ai/artifact-builds";
import { ArtifactPrompt } from "../artifact-prompt";
import { ArtifactBuilds } from "../artifact-builds";
import { DeleteArtifactButton } from "../delete-artifact-button";
import { setArtifactOnHome } from "@/app/dashboard-actions";
import { artifactWidgetKey } from "@/lib/finance/dashboard";

export default async function ArtifactPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ v?: string; full?: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/login"); }
  const { supabase, workspace } = context;
  const [{ id }, { v, full }] = await Promise.all([params, searchParams]);
  if (!/^[0-9a-f-]{36}$/i.test(id)) notFound();
  const [artifact, versions, layout, builds] = await Promise.all([
    supabase.from("artifacts").select("id, title").eq("workspace_id", workspace.id).eq("id", id).is("deleted_at", null).maybeSingle(),
    supabase.from("artifact_versions").select("version, prompt").eq("workspace_id", workspace.id).eq("artifact_id", id).order("version"),
    supabase.from("dashboard_layouts").select("items").eq("workspace_id", workspace.id).maybeSingle(),
    loadArtifactBuilds(supabase, workspace.id, id),
  ]);
  if (artifact.error || versions.error || layout.error) throw artifact.error ?? versions.error ?? layout.error;
  if (!artifact.data || !versions.data.length) notFound();
  const current = versions.data.find(item => String(item.version) === v) ?? versions.data.at(-1)!;
  const latest = versions.data.at(-1)!.version;
  // The frame reruns the saved queries on every open, so the page always shows today's data.
  const frame = <ArtifactFrame src={`/ai/artifacts/${id}/frame?v=${current.version}`} title={artifact.data.title} theme={context.settings.theme} className="size-full" />;
  const onHome = Array.isArray(layout.data?.items) && layout.data.items.includes(artifactWidgetKey(id));
  const at = (version: number, fullScreen = !!full) => `/ai/artifacts/${id}?v=${version}${fullScreen ? "&full=1" : ""}`;

  if (full) return <div className="fixed inset-0 z-50 bg-background">
    {frame}
    <Link href={at(current.version, false)} aria-label="Exit full screen" className="absolute right-3 top-3 inline-flex items-center gap-1 rounded-lg border border-border bg-card/90 px-3 py-1.5 text-xs shadow hover:bg-muted">
      <Minimize2 className="size-3.5" aria-hidden="true" />Exit</Link>
  </div>;

  return <main className="grid gap-4 p-4 lg:h-[calc(100dvh-1rem)] lg:grid-cols-[minmax(300px,380px)_1fr]">
    <aside className="flex min-h-0 flex-col gap-4">
      <div>
        <Link href="/ai/artifacts" className="text-xs text-muted-foreground hover:underline">← Artifacts</Link>
        <h1 className="mt-1 font-display text-2xl font-semibold tracking-tight">{artifact.data.title}</h1>
      </div>
      <ol aria-label="Versions" className="grid min-h-0 flex-1 content-start gap-2 overflow-y-auto">
        {versions.data.map(item => <li key={item.version}>
          <Link href={at(item.version)} aria-current={item.version === current.version ? "page" : undefined}
            className="block rounded-lg border border-border px-3 py-2 text-sm hover:bg-muted aria-[current=page]:border-primary aria-[current=page]:bg-muted">
            <span className="text-xs text-muted-foreground">v{item.version}</span> {item.prompt}</Link></li>)}
      </ol>
      <ArtifactBuilds builds={builds} artifactId={id} />
      <ArtifactPrompt artifactId={id} placeholder="Change something, e.g. “Add a toggle for selling the car”" />
      <DeleteArtifactButton id={id} title={artifact.data.title} />
    </aside>
    <section aria-label="Artifact" className="flex min-h-[70dvh] flex-col overflow-hidden rounded-xl border border-border">
      <div className="flex items-center justify-between gap-2 border-b border-border bg-card px-3 py-1.5 text-xs">
        <span className="inline-flex shrink-0 items-center gap-1 whitespace-nowrap">
          {current.version > 1 ? <Link href={at(current.version - 1)} aria-label="Previous version" className="rounded p-1 hover:bg-muted"><ChevronLeft className="size-3.5" /></Link> : <span className="p-1 opacity-30"><ChevronLeft className="size-3.5" /></span
          v{current.version} of {latest}
          {current.version < latest ? <Link href={at(current.version + 1)} aria-label="Next version" className="rounded p-1 hover:bg-muted"><ChevronRight className="size-3.5" /></Link> : <span className="p-1 opacity-30"><ChevronRight className="size-3.5" /></s
        </span>
        <span className="hidden truncate text-muted-foreground xl:inline">Live data · read-only · what-ifs are estimates</span>
        <span className="inline-flex shrink-0 items-center gap-1">
        <form action={setArtifactOnHome.bind(null, id, !onHome)}>
          <button type="submit" aria-pressed={onHome} title={onHome ? "Remove from Home" : "Show a compact version on Home"} className="inline-flex items-center gap-1 whitespace-nowrap rounded px-2 py-1 hover:bg-muted aria-pressed:text-brand">
            {onHome ? <Check className="size-3.5" aria-hidden="true" /> : <HousePlus className="size-3.5" aria-hidden="true" />}{onHome ? "On Home" : "Add to Home"}</button>
        </form>
        <Link href={at(current.version, true)} className="inline-flex shrink-0 items-center gap-1 whitespace-nowrap rounded px-2 py-1 hover:bg-muted"><Maximize2 className="size-3.5" aria-hidden="true" />Full screen</Link>
        </span>
      </div>
      <div className="min-h-0 flex-1">{frame}</div>
    </section>
  </main>;
}

